import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> belanja = Arrays.asList(25000, 12000, 40000, 8000);

        int total = belanja.stream().mapToInt(b -> b).sum();
        System.out.println("Total: " + total);

        double rata = belanja.stream().mapToInt(b -> b).average().orElse(0);
        System.out.println("Rata-rata: " + rata);

        int termahal = belanja.stream().mapToInt(b -> b).max().getAsInt();
        System.out.println("Termahal: " + termahal);

        int totalReduce = belanja.stream().reduce(0, (a, b) -> a + b);
        System.out.println("Total (reduce): " + totalReduce);
    }
}

